[hidden] { display: none !important; }

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  background: linear-gradient(135deg, #1e293b, #0f172a);
  color: #e2e8f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: #1e293b;
  border-radius: 24px;
  padding: 28px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  border: 1px solid #334155;
}

h1 {
  font-size: 1.6rem;
  text-align: center;
  margin-bottom: 8px;
  color: #f8fafc;
  letter-spacing: 0.5px;
}

.instructions {
  text-align: center;
  font-size: 0.95rem;
  color: #94a3b8;
  margin-bottom: 20px;
}

.game-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  gap: 12px;
  flex-wrap: wrap;
}

#swap-count {
  font-weight: 600;
  font-size: 1.1rem;
  color: #cbd5e1;
}

#shuffle-btn {
  background: #6366f1;
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 48px;
  min-width: 100px;
}

#shuffle-btn:hover { background: #4f46e5; }
#shuffle-btn:focus-visible { outline: 3px solid #a5b4fc; outline-offset: 2px; }
#shuffle-btn:active { transform: scale(0.97); }

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
  aspect-ratio: 1 / 1;
}

.tile {
  border-radius: 12px;
  border: 3px solid transparent;
  cursor: pointer;
  transition: transform 0.15s, border-color 0.15s, box-shadow 0.15s;
  min-width: 0;
  aspect-ratio: 1 / 1;
  position: relative;
}

.tile:hover { transform: scale(1.05); }
.tile:focus-visible { outline: 3px solid #facc15; outline-offset: 2px; }
.tile.selected { border-color: #facc15; box-shadow: 0 0 0 4px rgba(250, 204, 21, 0.4); }
.tile:active { transform: scale(0.95); }

/* Colors */
.tile[data-color="0"] { background: #ef4444; }
.tile[data-color="1"] { background: #3b82f6; }
.tile[data-color="2"] { background: #22c55e; }
.tile[data-color="3"] { background: #eab308; }

.solved {
  text-align: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: #4ade80;
  margin-top: 8px;
  animation: pop 0.3s ease;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

@media (max-width: 400px) {
  .game-container { padding: 20px 16px; }
  h1 { font-size: 1.4rem; }
  .grid { gap: 6px; }
  .tile { border-radius: 8px; }
  #shuffle-btn { padding: 10px 18px; font-size: 0.95rem; min-height: 44px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

(function () {
  'use strict';

  const SIZE = 4;
  const COLORS = 4;
  const gridEl = document.getElementById('grid');
  const swapCountEl = document.getElementById('swap-count');
  const solvedMsg = document.getElementById('solved-message');
  const shuffleBtn = document.getElementById('shuffle-btn');

  let tiles = [];
  let selected = null;
  let swaps = 0;

  function createSolvedGrid() {
    const arr = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        arr.push(r);
      }
    }
    return arr;
  }

  function shuffleArray(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function isSolved() {
    for (let r = 0; r < SIZE; r++) {
      const first = tiles[r * SIZE];
      for (let c = 1; c < SIZE; c++) {
        if (tiles[r * SIZE + c] !== first) return false;
      }
    }
    return true;
  }

  function countInversions(arr) {
    let inv = 0;
    for (let i = 0; i < arr.length; i++) {
      for (let j = i + 1; j < arr.length; j++) {
        if (arr[i] > arr[j]) inv++;
      }
    }
    return inv;
  }

  function isSolvable(arr) {
    const counts = {};
    arr.forEach(v => { counts[v] = (counts[v] || 0) + 1; });
    for (const k in counts) {
      if (counts[k] > SIZE) return false;
    }
    return countInversions(arr) % 2 === 0;
  }

  function generateShuffled() {
    let arr;
    let attempts = 0;
    do {
      arr = shuffleArray(createSolvedGrid());
      attempts++;
    } while ((isSolved() || !isSolvable(arr)) && attempts < 200);
    if (isSolved() || !isSolvable(arr)) {
      arr = createSolvedGrid();
      [arr[0], arr[1]] = [arr[1], arr[0]];
    }
    return arr;
  }

  function render() {
    gridEl.innerHTML = '';
    tiles.forEach((color, i) => {
      const tile = document.createElement('button');
      tile.type = 'button';
      tile.className = 'tile';
      tile.dataset.color = color;
      tile.dataset.index = i;
      tile.setAttribute('role', 'gridcell');
      tile.setAttribute('aria-label', 'Row ' + (Math.floor(i / SIZE) + 1) + ', Column ' + (i % SIZE + 1) + ', color ' + (color + 1));
      tile.addEventListener('click', () => handleTileClick(i));
      if (selected === i) tile.classList.add('selected');
      gridEl.appendChild(tile);
    });
    swapCountEl.textContent = 'Swaps: ' + swaps;
    solvedMsg.hidden = !isSolved();
  }

  function areAdjacent(a, b) {
    const ra = Math.floor(a / SIZE), ca = a % SIZE;
    const rb = Math.floor(b / SIZE), cb = b % SIZE;
    return Math.abs(ra - rb) + Math.abs(ca - cb) === 1;
  }

  function handleTileClick(index) {
    if (isSolved()) return;
    if (selected === null) {
      selected = index;
      render();
      return;
    }
    if (selected === index) {
      selected = null;
      render();
      return;
    }
    if (areAdjacent(selected, index)) {
      [tiles[selected], tiles[index]] = [tiles[index], tiles[selected]];
      selected = null;
      swaps++;
      render();
    } else {
      selected = index;
      render();
    }
  }

  function newGame() {
    tiles = generateShuffled();
    selected = null;
    swaps = 0;
    render();
  }

  shuffleBtn.addEventListener('click', newGame);

  document.addEventListener('keydown', (e) => {
    if (!selected) return;
    const r = Math.floor(selected / SIZE), c = selected % SIZE;
    let nr = r, nc = c;
    if (e.key === 'ArrowUp') nr = Math.max(0, r - 1);
    else if (e.key === 'ArrowDown') nr = Math.min(SIZE - 1, r + 1);
    else if (e.key === 'ArrowLeft') nc = Math.max(0, c - 1);
    else if (e.key === 'ArrowRight') nc = Math.min(SIZE - 1, c + 1);
    else return;
    e.preventDefault();
    const newIndex = nr * SIZE + nc;
    if (e.shiftKey && newIndex !== selected && areAdjacent(selected, newIndex)) {
      [tiles[selected], tiles[newIndex]] = [tiles[newIndex], tiles[selected]];
      selected = null;
      swaps++;
      render();
    } else {
      selected = newIndex;
      render();
      const focusTile = gridEl.children[newIndex];
      if (focusTile) focusTile.focus();
    }
  });

  newGame();
})();
